// `image-to-text`: an image to text about it, such as the text it shows, generated by a vision encoder-decoder such as TrOCR, as `transformers`' image-to-text pipeline gave it before `transformers` 5.

use crate::{
    error::Result,
    head::{Seq2SeqInput, Seq2SeqLm},
    model,
    processor::{
        image::{Image, ImageTransforms},
        text::TextTokenizer,
    },
    source::{LoadOptions, Source},
    task::{Pipeline, outputs::GeneratedText, seq2seq::Seq2SeqParameters},
};

#[derive(Debug)]
pub struct ImageToTextPipeline {
    model: Seq2SeqLm,
    processor: ImageTransforms,
    tokenizer: TextTokenizer,
    options: LoadOptions,
}

impl Pipeline for ImageToTextPipeline {
    type Input = Image;

    type Parameters = Seq2SeqParameters;

    type Output = GeneratedText;

    fn load(source: &Source, options: LoadOptions) -> Result<Self> {
        Ok(Self {
            model: model::load(source, options)?,
            processor: ImageTransforms::load(source)?,
            tokenizer: TextTokenizer::load(source)?,
            options,
        })
    }

    fn run_one(&self, image: &Self::Input, parameters: &Self::Parameters) -> Result<Self::Output> {
        let pixels =
            self.processor
                .preprocess(image, self.options.device, self.options.data_type)?;
        Ok(GeneratedText {
            generated_text: self.model.generate_from(
                &self.tokenizer,
                Seq2SeqInput::Pixels(&pixels),
                parameters.max_new_tokens,
                parameters.compile,
            )?,
        })
    }
}
